member.remarks:
Permutation generated by code:

// First 1850 fractional digit of Pi number. 
byte[] key = new BigInteger("14159265358979323846...5068006422512520511").ToByteArray();
s = 0;
P = new byte[256];
for (int i = 0; i < 256; i++) 
{
    P[i] = (byte) i;
}
for (int m = 0; m < 768; m++) 
{
    s = P[(s + P[m & 0xff] + key[m % key.length]) & 0xff];
    byte temp = P[m & 0xff];
    P[m & 0xff] = P[s & 0xff];
    P[s & 0xff] = temp;
}

